// Some portions generated by Codex. Benchmark-only HTTP client; no browser rendering claim.
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
const [base='http://127.0.0.1:18080', size='100000', out='client.json', mode='measure'] = process.argv.slice(2);
const expected = Number(process.env.EXPECTED_ROWS || 100000);
const width = Number(process.env.WIDTH || 6);
import {query} from './query.mjs';
const ns='urn:overlay-optional:';
const url=base+'/rdf4j-workbench/repositories/bench/query';
const session=await fetch(url,{headers:{Accept:'text/html'}});
assert.equal(session.status,200,await session.text());
const cookies=session.headers.getSetCookie().map(x=>x.split(';')[0]);
const csrf=cookies.find(x=>x.startsWith('rdf4j-workbench-csrf='))?.split('=')[1];
assert.ok(csrf,'CSRF cookie missing');
const params=new URLSearchParams({action:'exec',ref:'text',query,queryLn:'SPARQL',infer:'true','query-timeout':'600','lmdb-forced-strategy':'irKernel','batch-offset':'0','batch-size':size});
const before=await (await fetch(base+'/bench-metrics')).json();
const start=performance.now();
const response=await fetch(url,{method:'POST',body:params,headers:{Accept:'application/vnd.rdf4j.workbench-query-v2+ndjson',Cookie:cookies.join('; '),'X-RDF4J-CSRF-Token':csrf,Origin:base}});
const headersMs=performance.now()-start;
const contentEncoding=response.headers.get('content-encoding');
if(response.status!==200)throw Error(`HTTP ${response.status}: ${await response.text()}`);
assert.match(response.headers.get('content-type')||'',/^application\/vnd\.rdf4j\.workbench-query-v2\+ndjson/);
let sum=0n,sum2=0n;let rowRecords=0,firstRecordRows=null,firstRecordBytes=null;
let carry='',bytes=0,rows=0,firstRowMs=null,batchMs=null,endMs=null,terminal=null,vars=null,records=0;
const decoder=new TextDecoder('utf-8',{fatal:true}),digest=crypto.createHash('sha256');
const seen=mode==='validate'?new Uint8Array(Math.ceil(expected/8)):null;
for await(const chunk of response.body) {
 bytes+=chunk.length; carry+=decoder.decode(chunk,{stream:true});
 let p;
 while((p=carry.indexOf('\n'))>=0){
  const line=carry.slice(0,p);carry=carry.slice(p+1);if(!line)continue;
  const record=JSON.parse(line);records++;
  if(record.type==='error') throw Error(JSON.stringify(record));
  if(record.type==='head') {assert.equal(record.version,2);assert.equal(record['term-encoding'],'array');}
  if(record.type==='vars') {vars=record.values; assert.equal(vars.length,width);}
  if(record.type==='rows') {
   firstRowMs??=performance.now()-start;
   rowRecords++;if(firstRecordRows===null){firstRecordRows=record.values.length;firstRecordBytes=Buffer.byteLength(line,'utf8')+1;}
   // Timed trials count rows; a separate validation run hashes and checks each complete emitted tuple.
   if(mode==='validate') {
    digest.update(line);
    for(const row of record.values) { validateRow(row,vars,seen); let h=1n; for(const term of row)h=BigInt.asIntN(64,31n*h+termHash(term)); sum=BigInt.asIntN(64,sum+h); const x=BigInt.asUintN(64,h*0x9e3779b97f4a7c15n); const mixed=BigInt.asUintN(64,(x<<23n)|(x>>41n))^(BigInt.asUintN(64,h)>>17n); sum2=BigInt.asIntN(64,sum2+mixed); }
   }
   rows+=record.values.length;
   if(rows>=Number(size))batchMs??=performance.now()-start;
  }
  if(record.type==='end'){assert.equal(terminal,null);terminal=record.metadata;endMs=performance.now()-start;}
 }
}
carry+=decoder.decode();assert.equal(carry.trim(),'');assert.ok(terminal,'Missing terminal end record');
assert.equal(rows,Math.min(Number(size),expected));
assert.equal(Number(terminal['total-result-count']),expected);
assert.equal(terminal['query-result-status'],'completed');
const eofMs=performance.now()-start;
const after=await (await fetch(base+'/bench-metrics')).json();
if(mode==='validate' && expected===100000 && width===6){assert.equal(sum.toString(),'1899306305404719472');assert.equal(sum2.toString(),'3694550068168048289');}
const result={contentEncoding,rowRecords,firstRecordRows,firstRecordBytes,fullTermChecksum:sum.toString(),fullTermChecksum2:sum2.toString(),mode,querySha256:crypto.createHash('sha256').update(query).digest('hex'),expected,size:Number(size),headersMs,firstRowMs,batchMs,endMs,eofMs,rows,bytes,records,terminal,checksum:mode==='validate'?digest.digest('hex'):null,before,after};
fs.writeFileSync(out,JSON.stringify(result,null,2));console.log(JSON.stringify(result));
function validateRow(row,vars,seen){
 assert.equal(row.length,width);
 const get=n=>row[vars.indexOf(n)];
 const group=Number(get('s')[1].substring((ns+'group/').length));assert.ok(Number.isInteger(group)&&group>=0&&group<expected/1000);
 assert.deepEqual(get('s'),[0,ns+'group/'+group]);
 assert.deepEqual(get('label'),[2,'Group label '+group,'http://www.w3.org/2001/XMLSchema#string']);
 assert.deepEqual(get('seed'),[2,'Seed '+group,'http://www.w3.org/2001/XMLSchema#string']);
 let index=group;
 for(let a=0;a<3;a++){
  const prefix=ns+`node/${group}/${a}/`, term=get('n'+a);assert.equal(term[0],0);assert.ok(term[1].startsWith(prefix));
  const member=Number(term[1].substring(prefix.length));assert.ok(Number.isInteger(member)&&member>=0&&member<10);index=index*10+member;
  if(width===30) for(let c=0;c<8;c++){
   const term=get(`v${a}_${c}`);
   if(c>=4 && member%7===0)assert.equal(term,null);
   else assert.deepEqual(term,[2,`Shared lexical prefix é 漢字 ${group}/${a}/${member}/${c}`,null,'nb']);
  }
 }
 const mask=1<<(index%8);assert.equal(seen[index>>3]&mask,0,'Duplicate tuple');seen[index>>3]|=mask;
}

function javaHash(s){let h=0;for(let i=0;i<s.length;i++)h=(Math.imul(h,31)+s.charCodeAt(i))|0;return BigInt(h);}
function termHash(t){if(t===null)return 0n;let h=31n*javaHash(t[1])+(t[0]===0?1n:t[0]===1?2n:3n);if(t[0]===2){h=31n*h+javaHash(t[2]||(t[3]?'http://www.w3.org/1999/02/22-rdf-syntax-ns#langString':'http://www.w3.org/2001/XMLSchema#string'));h=31n*h+javaHash(t[3]||'');}return BigInt.asIntN(64,h);}
